#!/usr/bin/env python3
"""Keep the runtime executable checks aligned with the audited distribution."""
from __future__ import annotations
import argparse
from pathlib import Path
from dolphin_distribution import inventory
from fetch_runtime import load_manifest

ROOT = Path(__file__).resolve().parent.parent


def policy(manifest: dict) -> str:
    files = inventory(manifest)
    lines = ["#ifndef GDOX_DOLPHIN_PAYLOAD_H", "#define GDOX_DOLPHIN_PAYLOAD_H",
             "/* Generated by scripts/generate_dolphin_policy.py. */"]
    for label, name in (("PAYLOAD", "bin/dolphin-emu"), ("LAUNCHER", "dolphin")):
        pin = files[name]
        lines += [f"#define GDOX_DOLPHIN_{label}_BYTES UINT64_C({pin['size']})",
                  f"#define GDOX_DOLPHIN_{label}_SHA256 \"{pin['sha256']}\""]
    return "\n".join([*lines, "#endif", ""])


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = ROOT / "src/platform/dolphin_payload.h"
    expected = policy(load_manifest())
    if args.check:
        if output.read_text() != expected:
            raise SystemExit("Dolphin generated policy is stale")
    else:
        output.write_text(expected)
